import * as React from "react"
import { ChevronDown, ChevronLeft, ChevronRight } from "lucide-react"

import { cn } from "@/lib/utils"

type TableProps = React.HTMLAttributes<HTMLTableElement> & {
  pagination?: React.ReactNode
  maxHeight?: number | string
  scrollContainerClassName?: string
  stickyHeader?: boolean
}

const Table = React.forwardRef<HTMLTableElement, TableProps>(
  (
    { className, pagination, maxHeight, scrollContainerClassName, stickyHeader, ...props },
    ref
  ) => (
    <div className="relative w-full overflow-hidden rounded-[8px] border border-[#e6e6e6] bg-white">
      <div
        className={cn("ml-table-scroll w-full overflow-auto", scrollContainerClassName)}
        style={
          maxHeight
            ? { maxHeight: typeof maxHeight === "number" ? `${maxHeight}px` : maxHeight }
            : undefined
        }
      >
        <table
          ref={ref}
          className={cn(
            "w-full caption-bottom text-[14px] leading-[20px]",
            stickyHeader
              ? "[&_thead]:sticky [&_thead]:top-0 [&_thead]:z-10 [&_thead]:bg-[#fafafa]"
              : undefined,
            className
          )}
          {...props}
        />
      </div>
      {pagination ? <div className="w-full">{pagination}</div> : null}
    </div>
  )
)
Table.displayName = "Table"

