TablePaginationPage.displayName = "TablePaginationPage"

type TablePaginationGoToProps = React.HTMLAttributes<HTMLDivElement> & {
  label?: string
  pageLabel?: string
  placeholder?: string
  icon?: React.ReactNode
}

type TablePaginationTotalEntriesProps = React.HTMLAttributes<HTMLDivElement> & {
  label?: string
  total?: string | number
}

const TablePaginationTotalEntries = React.forwardRef<
  HTMLDivElement,
  TablePaginationTotalEntriesProps
>(({ className, label = "Total entries:", total = "-", ...props }, ref) => (
  <div
    ref={ref}
    className={cn("flex items-center gap-1 text-[14px] font-normal leading-[20px]", className)}
    {...props}
  >
    <span className="text-[#4f4d55]">{label}</span>
    <span className="text-[#1d1c20]">{total}</span>
  </div>
))
TablePaginationTotalEntries.displayName = "TablePaginationTotalEntries"

const TablePaginationGoTo = React.forwardRef<
  HTMLDivElement,
  TablePaginationGoToProps
>(
  (
    {
      className,
      label = "Go to page:",
      pageLabel = "-",
      placeholder = "-",
      icon,
      ...props
    },
    ref
  ) => (
  <div
    ref={ref}
    className={cn("col-start-3 flex items-center gap-[13px] justify-self-end", className)}
    {...props}
  >
    <span className="text-[14px] font-normal leading-[20px] text-foreground">
      {label}
    </span>
    <button
      type="button"
      aria-haspopup="listbox"
      className="flex h-8 min-w-[72px] items-center justify-between gap-2 rounded-[8px] border border-[#e6e6e6] bg-white px-3 text-[12px] leading-[16px] text-foreground shadow-sm"
    >
      <span className={pageLabel === placeholder ? "text-[#7f7d83]" : undefined}>
        {pageLabel === placeholder ? placeholder : pageLabel}
      </span>
      {icon || <ChevronDown className="h-4 w-4 text-[#7f7d83]" />}
    </button>
  </div>
  )
)
TablePaginationGoTo.displayName = "TablePaginationGoTo"

const TablePaginationIcon = ({
  className,
  direction,
}: {
  className?: string
  direction: "left" | "right"
}) =>
  direction === "left" ? (
    <ChevronLeft className={cn("h-4 w-4", className)} />
  ) : (
    <ChevronRight className={cn("h-4 w-4", className)} />
  )

export {
  Table,
  TableHeader,
  TableBody,
  TableFooter,
  TableHead,
  TableRow,
  TableCell,
  TableCaption,
  TablePagination,
  TablePaginationEntries,
  TablePaginationContent,
  TablePaginationPages,
  TablePaginationButton,
  TablePaginationPage,
  TablePaginationTotalEntries,
  TablePaginationGoTo,
  TablePaginationIcon,
}
